import {
  ChangeDetectionStrategy,
  Component,
  Inject,
  OnDestroy,
  OnInit,
  Renderer2,
  inject
} from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { PROFILE_DATA, ProfileData } from '../../businesscard/profile-card/profile-card.model';
import { environment } from '../../../environments/environment';

@Component({
  selector: 'app-card',
  standalone: true,
  imports: [],
  templateUrl: './card.component.html',
  styleUrl: './card.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CardComponent implements OnInit, OnDestroy {
  readonly profile: ProfileData = inject(PROFILE_DATA);
  readonly base = environment.url + '/images/businesscard/';

  constructor(
    private renderer: Renderer2,
    @Inject(DOCUMENT) private document: Document
  ) {}

  ngOnInit(): void {
    this.toggleBusinessCardPageClass(true);
  }

  ngOnDestroy(): void {
    this.toggleBusinessCardPageClass(false);
  }

  private toggleBusinessCardPageClass(shouldAdd: boolean): void {
    const method = shouldAdd ? 'addClass' : 'removeClass';
    const html = this.document.documentElement;
    const body = this.document.body;

    if (html) {
      this.renderer[method](html, 'business-card-page');
    }

    if (body) {
      this.renderer[method](body, 'business-card-page');
    }
  }
}
