// shared/profile-card/profile-card.model.ts
import { InjectionToken } from '@angular/core';

export interface SocialLink {
  href: string;
  icon: string;   // path to icon asset
  alt: string;
  width?: number;
  height?: number;
}

export interface ProfileData {
  name: string;
  title: string;
  photo: string;       // asset path
  phone: string;
  email: string;
  fileName?: string;   // for vCard download
  vcfPath: string;
  socialLinks: SocialLink[];
}

// InjectionToken lets each page component provide its own data
export const PROFILE_DATA = new InjectionToken<ProfileData>('PROFILE_DATA');